arguments.command:
cd /tmp/waza-33781438 && mkdir -p tests/generated && cat > tests/generated/TC-001.spec.ts <<'EOF'
import { test, expect } from "@playwright/test";

test.describe("TC-001: Locked-out user cannot log in", () => {
  test("should reject login for a locked-out user", async ({ page }) => {
    await page.goto("/");

    const username = page.locator('[data-test="username"]');
    await username.fill("locked_out_user");
    await expect(username).toHaveValue("locked_out_user");

    const password = page.locator('[data-test="password"]');
    await password.fill("secret_sauce");
    await expect(password).toHaveValue("secret_sauce");
    await expect(password).toHaveAttribute("type", "password");

    await page.locator('[data-test="login-button"]').click();
    await expect(page.locator('[data-test="error"]')).toHaveText(
      "Epic sadface: Sorry, this user has been locked out."
    );

    await expect(page).not.toHaveURL(/inventory/);
    await expect(page.locator('[data-test="inventory-list"]')).toHaveCount(0);
  });
});
EOF
npm test -- tests/generated/TC-001.spec.ts 2>&1 | tail -15

